// Oeste LIVEBadge — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/live-badge

export function LIVEBadge() {
  return (
    <span className="inline-flex items-center gap-1.5">
      <span aria-hidden="true" className="inline-block h-2 w-2 rounded-full bg-[var(--color-live)]" />
      <span className="text-[13px] font-bold leading-[1] tracking-[0.06em] text-[var(--color-live)] uppercase">Live</span>
    </span>
  );
}
